Item.method_code:
Innovator inn = this.getInnovator();

string relId = this.getProperty("relId","");
string relTypeName = this.getProperty("relTypeName","");

using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
    var relationItem = inn.newItem(relTypeName,"delete");
    relationItem.setID(relId);
    relationItem = relationItem.apply();
    if(relationItem.isError())
    {
        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
    }
}
return this;
